// ConfirmButton — a two-step confirm button (#…): click to arm, click again to confirm. Supports a
// pending/spinner state for an async onConfirm, and blurs back to unarmed. Promoted from harvested
// into base-studio-code verbatim -- it was already a genuinely self-contained primitive.
import { useState, type CSSProperties } from "react";

interface ConfirmButtonProps {
  label: string;
  armedLabel: string;
  onConfirm: () => void | Promise<void>;
  /** Shown in place of armedLabel while a Promise-returning onConfirm is in flight. */
  pendingLabel?: string;
  /** "md" (8×14, the reset cards) — the default — or "sm" (5×10, the inline list-row actions). */
  size?: "sm" | "md";
  disabled?: boolean;
  danger?: boolean;
  style?: CSSProperties;
}
function Spinner({ size = 11 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" aria-hidden="true" style={{ animation: "bsc-confirm-spin 0.7s linear infinite", flexShrink: 0, marginRight: 6, verticalAlign: "-2px" }}>
      <circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeDasharray="34 100" opacity="0.85" />
      <style>{"@keyframes bsc-confirm-spin{to{transform:rotate(360deg)}}"}</style>
    </svg>
  );
}
export function ConfirmButton({
  label = "Delete", armedLabel = "Confirm — can't be undone", onConfirm = () => {}, pendingLabel = "working…", size = "md", disabled = false, danger = true, style,
}: Partial<ConfirmButtonProps>) {
  const [armed, setArmed] = useState(false);
  const [pending, setPending] = useState(false);
  const sm = size === "sm";
  const busy = disabled || pending;
  return (
    <button
      className="mono"
      disabled={busy}
      aria-busy={pending || undefined}
      onClick={() => {
        if (pending) return;
        if (armed) {
          setArmed(false);
          setPending(true);
          Promise.resolve(onConfirm()).finally(() => setPending(false));
        } else {
          setArmed(true);
        }
      }}
      onBlur={() => { if (!pending) setArmed(false); }}
      style={{
        ...(sm ? {} : { alignSelf: "flex-start" }),
        padding: sm ? "5px 10px" : "8px 14px",
        borderRadius: 6,
        cursor: busy ? "default" : "pointer",
        fontSize: sm ? 10.5 : 11.5,
        ...(disabled && !pending ? { opacity: 0.5 } : {}),
        background: armed && danger ? "var(--danger)" : "var(--bg-elev)",
        color: armed && danger ? "var(--bg-canvas)" : danger ? "var(--danger)" : "var(--fg)",
        border: "1px solid " + (armed && danger
          ? "var(--danger)"
          : danger ? "color-mix(in oklch, var(--danger), transparent 55%)" : "var(--border)"),
        ...style,
      }}
    >{pending && <Spinner size={sm ? 10 : 11} />}{pending ? pendingLabel : armed ? armedLabel : label}</button>
  );
}
